use crate::aap::caps::state_read;

struct Node;

/// Keys under which the subscription list may be stored, tried in order.
const KEYS: &[&str] = &["urls", "subscriptions", "feeds"];

/// Parse a JSON array of strings. Returns None if the text is not one.
fn parse_json_string_array(text: &str) -> Option<Vec<String>> {
    let mut chars = text.trim().chars().peekable();
    if chars.next()? != '[' {
        return None;
    }
    let mut out = Vec::new();
    loop {
        while matches!(chars.peek(), Some(c) if c.is_whitespace()) {
            chars.next();
        }
        match chars.next()? {
            ']' => break,
            ',' => continue,
            '"' => {
                let mut s = String::new();
                loop {
                    match chars.next()? {
                        '"' => break,
                        '\\' => match chars.next()? {
                            '"' => s.push('"'),
                            '\\' => s.push('\\'),
                            '/' => s.push('/'),
                            'b' => s.push('\u{8}'),
                            'f' => s.push('\u{c}'),
                            'n' => s.push('\n'),
                            'r' => s.push('\r'),
                            't' => s.push('\t'),
                            'u' => {
                                let mut code = 0u32;
                                for _ in 0..4 {
                                    code = code * 16 + chars.next()?.to_digit(16)?;
                                }
                                s.push(char::from_u32(code).unwrap_or('\u{fffd}'));
                            }
                            _ => return None,
                        },
                        c => s.push(c),
                    }
                }
                out.push(s);
            }
            _ => return None,
        }
    }
    Some(out)
}

/// Parse a stored value: a JSON array of strings, or a newline/comma/whitespace
/// separated list, with `#` comment lines ignored.
fn parse_urls(value: &str) -> Vec<String> {
    let raw: Vec<String> = match parse_json_string_array(value) {
        Some(list) => list,
        None => value
            .lines()
            .map(str::trim)
            .filter(|l| !l.is_empty() && !l.starts_with('#'))
            .flat_map(|l| {
                l.split(|c: char| c == ',' || c.is_whitespace())
                    .map(|s| s.to_string())
                    .collect::<Vec<_>>()
            })
            .collect(),
    };

    let mut urls: Vec<String> = Vec::new();
    for u in raw {
        let u = u.trim().to_string();
        if u.is_empty() || urls.contains(&u) {
            continue;
        }
        urls.push(u);
    }
    urls
}

impl Guest for Node {
    fn run(_info: RunInfo) -> SubscriptionList {
        for key in KEYS {
            if let Some(value) = state_read::get(key) {
                let urls = parse_urls(&value);
                if !urls.is_empty() {
                    return SubscriptionList { urls };
                }
            }
        }
        // The contract requires `urls` to be present; with no subscriptions
        // stored there is no honest output to produce, so fail the run.
        panic!("no subscriptions found in the 'subscriptions' store");
    }
}

export!(Node);
